const p=$json.body;
if(!p || typeof p!=='object' || Array.isArray(p))throw new Error('Requête invalide');
let body, endpoint;
if(p.operation==='search'){
 if(Object.keys(p).sort().join(',')!=='date,fond,operation,query')throw new Error('Champs inconnus');
 if(!['CODE_DATE','LODA_DATE'].includes(p.fond))throw new Error('Fonds interdit');
 if(typeof p.query!=='string'||p.query.length<3||p.query.length>100||!/^\p{L}+(?:[ '\u2019-]\p{L}+){0,11}$/u.test(p.query))throw new Error('Mots-clés invalides');
 const epoch=Date.parse(p.date+'T12:00:00Z');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!Number.isFinite(epoch)||new Date(epoch).toISOString().slice(0,10)!==p.date)throw new Error('Date invalide');
 endpoint='/search';
 body={fond:p.fond,recherche:{champs:[{typeChamp:'ARTICLE',criteres:[{typeRecherche:'TOUS_LES_MOTS_DANS_UN_CHAMP',valeur:p.query,operateur:'ET'}],operateur:'ET'}],filtres:[{facette:'DATE_VERSION',singleDate:epoch}],pageNumber:1,pageSize:5,operateur:'ET',sort:'PERTINENCE',typePagination:'ARTICLE'}};
}else if(p.operation==='reference'){
 if(Object.keys(p).sort().join(',')!=='code,date,numero,operation')throw new Error('Champs inconnus');
 if(typeof p.code!=='string'||p.code.length>180||!/^Code [\p{L} '\u2019-]+$/u.test(p.code))throw new Error('Code invalide');
 if(typeof p.numero!=='string'||!(/^[LRD]?[.*]?\s*\d+(?:-\d+){0,4}$/).test(p.numero)||p.numero.length>30)throw new Error('Numéro invalide');
 const epoch=Date.parse(p.date+'T12:00:00Z');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!Number.isFinite(epoch)||new Date(epoch).toISOString().slice(0,10)!==p.date)throw new Error('Date invalide');
 endpoint='/search';
 body={fond:'CODE_DATE',recherche:{champs:[{typeChamp:'NUM_ARTICLE',criteres:[{typeRecherche:'EXACTE',valeur:p.numero,operateur:'ET'}],operateur:'ET'}],filtres:[{facette:'DATE_VERSION',singleDate:epoch},{facette:'NOM_CODE',valeurs:[p.code]}],pageNumber:1,pageSize:5,operateur:'ET',sort:'PERTINENCE',typePagination:'ARTICLE'}};
}else if(p.operation==='article'){
 if(Object.keys(p).sort().join(',')!=='id,operation'||!/^LEGIARTI\d{12}$/.test(p.id))throw new Error('Article invalide');
 endpoint='/consult/getArticle';body={id:p.id};
}else throw new Error('Opération interdite');
return [{json:{endpoint,body,request:p}}];
